const parent = $input.first().json;
const extraction = parent.extraction ?? parent.output;
const errors = [];
if (!extraction || typeof extraction !== 'object') errors.push('extraction or output is required');
const x = extraction || {};
if (x.schema_version !== '1.0.0') errors.push('extraction.schema_version must be 1.0.0');
if (typeof x.run_id !== 'string' || !x.run_id.trim()) errors.push('extraction.run_id is required');
if (parent.run_id !== x.run_id) errors.push('parent run_id must match extraction.run_id');
if (!(parent.orchestration_context?.parent_trace_id || '').trim()) errors.push('orchestration_context.parent_trace_id is required');
if (!['complete','partial','no_requirements'].includes(x.extraction_status)) errors.push('invalid extraction_status');
if (typeof x.summary !== 'string' || !x.summary.trim()) errors.push('summary is required');
for (const field of ['items','contradictions','missing_information','extractor_notes']) if (!Array.isArray(x[field])) errors.push(field + ' must be an array');
if (Array.isArray(x.items)) { const ids = new Set(); for (const item of x.items) { if (!item.id || ids.has(item.id)) errors.push('item IDs must be present and unique'); ids.add(item.id); if (!Array.isArray(item.evidence) || item.evidence.length === 0) errors.push('evidence missing for ' + item.id); } }
if (errors.length) throw new Error('Parent extraction input invalid: ' + errors.join('; '));
return [{json:{...x,input_validation:{valid:true,validated_at:new Date().toISOString(),contract:'requirement-extraction.schema.json'},orchestration_context:parent.orchestration_context}}];

