const raw = $json.text ?? $json.output ?? $json.response;
if (typeof raw !== 'string') throw new Error('Gap Analyzer did not return text');
const fence = String.fromCharCode(96).repeat(3);
let cleaned = raw.trim();
if (cleaned.startsWith(fence)) cleaned = cleaned.replace(fence + 'json', '').replace(fence, '').trim();
let result;
try { result = JSON.parse(cleaned); } catch (e) { throw new Error('Gap Analysis is not valid JSON: ' + e.message); }
const ctx = $("Create Gap Trace Context").first().json;
const extraction = ctx.extraction;
const errors = [];
const exact = (obj, fields, label) => { const actual = Object.keys(obj || {}).sort(); const expected = [...fields].sort(); if (JSON.stringify(actual) !== JSON.stringify(expected)) errors.push(label + ' fields must be exactly: ' + expected.join(', ')); };
const str = (v, label) => { if (typeof v !== 'string' || !v.trim()) errors.push(label + ' must be a non-empty string'); };
const arr = (v, label) => { if (!Array.isArray(v)) errors.push(label + ' must be an array'); };
const sev = new Set(['low','medium','high','blocking']);
const itemIds = new Set((extraction.items || []).map(x => x.id));
const missingIds = new Set((extraction.missing_information || []).map(x => x.id));
const sourceRiskIds = new Set((extraction.items || []).filter(x => x.type === 'risk').map(x => x.id));
exact(result, ['schema_version','run_id','information_sufficiency','generation_allowed','recommended_action','decision_reason','gaps','contradictions','risks'], 'Top-level');
if (result.schema_version !== '1.0.0') errors.push('schema_version must be 1.0.0');
if (result.run_id !== extraction.run_id || result.run_id !== ctx.trace_context.run_id) errors.push('run_id must match extraction and trace context');
if (!['sufficient','partially_sufficient','insufficient'].includes(result.information_sufficiency)) errors.push('Invalid information_sufficiency');
if (typeof result.generation_allowed !== 'boolean') errors.push('generation_allowed must be boolean');
if (!['proceed','proceed_with_tbd','request_clarification','block_generation'].includes(result.recommended_action)) errors.push('Invalid recommended_action');
str(result.decision_reason, 'decision_reason');
arr(result.gaps, 'gaps'); arr(result.contradictions, 'contradictions'); arr(result.risks, 'risks');
const combo = result.information_sufficiency + '|' + result.generation_allowed + '|' + result.recommended_action;
const combos = new Set(['sufficient|true|proceed','partially_sufficient|true|proceed_with_tbd','partially_sufficient|false|request_clarification','insufficient|false|request_clarification','insufficient|false|block_generation']);
if (!combos.has(combo)) errors.push('Decision fields are inconsistent');
const seen = new Set();
const refs = (xs, known, label) => { arr(xs, label); for (const id of xs || []) if (!known.has(id)) errors.push(label + ' references unknown ID ' + id); };
for (const g of result.gaps || []) {
  exact(g, ['id','category','description','severity','clarification_question','related_item_ids','source_missing_information_ids'], 'Gap ' + (g.id || '?'));
  if (!/^GAP-[0-9]{3}$/.test(g.id || '')) errors.push('Invalid gap ID ' + g.id);
  str(g.category,'gap.category'); str(g.description,'gap.description'); str(g.clarification_question,'gap.clarification_question');
  if (!sev.has(g.severity)) errors.push('Invalid gap severity');
  refs(g.related_item_ids,itemIds,'gap.related_item_ids'); refs(g.source_missing_information_ids,missingIds,'gap.source_missing_information_ids');
  if (!(g.related_item_ids?.length || g.source_missing_information_ids?.length)) errors.push(g.id + ' requires an extraction trace link');
  if (seen.has(g.id)) errors.push('Duplicate ID ' + g.id); seen.add(g.id);
}
for (const c of result.contradictions || []) {
  exact(c, ['id','description','severity','related_item_ids'], 'Contradiction ' + (c.id || '?'));
  if (!/^CTR-[0-9]{3}$/.test(c.id || '')) errors.push('Invalid contradiction ID ' + c.id);
  str(c.description,'contradiction.description'); if (!sev.has(c.severity)) errors.push('Invalid contradiction severity');
  refs(c.related_item_ids,itemIds,'contradiction.related_item_ids');
  if (!c.related_item_ids?.length) errors.push(c.id + ' requires related_item_ids');
  if (seen.has(c.id)) errors.push('Duplicate ID ' + c.id); seen.add(c.id);
}
for (const k of result.risks || []) {
  exact(k, ['id','description','severity','related_item_ids','source_risk_ids'], 'Risk ' + (k.id || '?'));
  if (!/^RSK-[0-9]{3}$/.test(k.id || '')) errors.push('Invalid risk ID ' + k.id);
  str(k.description,'risk.description'); if (!sev.has(k.severity)) errors.push('Invalid risk severity');
  refs(k.related_item_ids,itemIds,'risk.related_item_ids'); refs(k.source_risk_ids,sourceRiskIds,'risk.source_risk_ids');
  if (!(k.related_item_ids?.length || k.source_risk_ids?.length)) errors.push(k.id + ' requires an extraction trace link');
  if (seen.has(k.id)) errors.push('Duplicate ID ' + k.id); seen.add(k.id);
}
const hasBlocking = [...(result.gaps || []), ...(result.contradictions || [])].some(x => ['high','blocking'].includes(x.severity));
if (hasBlocking && result.generation_allowed) errors.push('High/blocking issues must block generation');
if (errors.length) throw new Error('Gap Analysis validation failed: ' + errors.join('; '));
return [{json:{gap_analysis:result,validation:{schema_version:'1.0.0',structurally_valid:true,decision_consistent:true,traceability_valid:true,validated_at:new Date().toISOString()},extraction,trace_context:ctx.trace_context}}];

const input = $json;
const g = input.gap_analysis;
const v = input.validation;
if (!g || !v?.structurally_valid || !v?.decision_consistent || !v?.traceability_valid) {
  throw new Error('Generation gate requires a fully validated Gap Analysis');
}
const key = [g.information_sufficiency, g.generation_allowed, g.recommended_action].join('|');
const routes = {
  'sufficient|true|proceed': {
    gate_status: 'eligible_for_human_approval',
    route: 'human_review',
    prd_generation_eligible: true,
    requires_tbd: false
  },
  'partially_sufficient|true|proceed_with_tbd': {
    gate_status: 'eligible_with_tbd',
    route: 'human_review_with_tbd',
    prd_generation_eligible: true,
    requires_tbd: true
  },
  'partially_sufficient|false|request_clarification': {
    gate_status: 'clarification_required',
    route: 'clarification',
    prd_generation_eligible: false,
    requires_tbd: false
  },
  'insufficient|false|request_clarification': {
    gate_status: 'clarification_required',
    route: 'clarification',
    prd_generation_eligible: false,
    requires_tbd: false
  },
  'insufficient|false|block_generation': {
    gate_status: 'generation_blocked',
    route: 'blocked',
    prd_generation_eligible: false,
    requires_tbd: false
  }
};
const decision = routes[key];
if (!decision) throw new Error('Unsupported generation-gate decision: ' + key);
if (decision.prd_generation_eligible !== g.generation_allowed) {
  throw new Error('Gate eligibility conflicts with generation_allowed');
}
return [{
  json: {
    ...input,
    generation_gate: {
      schema_version: '1.0.0',
      run_id: g.run_id,
      ...decision,
      human_approval_required: decision.prd_generation_eligible,
      decision_source: {
        information_sufficiency: g.information_sufficiency,
        generation_allowed: g.generation_allowed,
        recommended_action: g.recommended_action
      },
      evaluated_at: new Date().toISOString()
    }
  }
}];

const data = $json;
const ctx = data.trace_context;
const randomHex = length => Array.from({length}, () => Math.floor(Math.random()*16).toString(16)).join('');
const traceId = randomHex(32);
const rootSpanId = randomHex(16);
const generationSpanId = randomHex(16);
