  startTimeUnixNano:startNano.toString(), endTimeUnixNano:nowNano.toString(),
  attributes:[...shared,attr('langfuse.observation.type','SPAN'),attr('langfuse.observation.input',data.extraction),attr('langfuse.observation.output',{gap_analysis:data.gap_analysis,generation_gate:data.generation_gate})],
  status:{code:1}
};
const generation = {
  traceId, spanId:generationSpanId, parentSpanId:rootSpanId, name:'gap-analyzer', kind:1,
  startTimeUnixNano:startNano.toString(), endTimeUnixNano:generationEnd.toString(),
  attributes:[...shared,attr('langfuse.observation.type','GENERATION'),attr('langfuse.observation.model.name','gpt-5.6-terra'),attr('langfuse.observation.input',{extraction:data.extraction,prompt_version:ctx.prompt_version}),attr('langfuse.observation.output',data.gap_analysis),attr('langfuse.observation.metadata.reasoning_effort','medium'),attr('langfuse.observation.metadata.usage_capture_status','not_exposed_by_n8n_agent_output')],
  status:{code:1}
};
const validation = {
  traceId, spanId:validationSpanId, parentSpanId:rootSpanId, name:'validate-gap-analysis', kind:1,
  startTimeUnixNano:validationStart.toString(), endTimeUnixNano:validationEnd.toString(),
  attributes:[...shared,attr('langfuse.observation.type','SPAN'),attr('langfuse.observation.input',data.gap_analysis),attr('langfuse.observation.output',data.validation)],
  status:{code:1}
