const gate = {
  traceId, spanId:gateSpanId, parentSpanId:rootSpanId, name:'deterministic-generation-gate', kind:1,
  startTimeUnixNano:gateStart.toString(), endTimeUnixNano:nowNano.toString(),
  attributes:[...shared,attr('langfuse.observation.type','SPAN'),attr('langfuse.observation.input',data.generation_gate.decision_source),attr('langfuse.observation.output',data.generation_gate)],
  status:{code:1}
};
return [{json:{
  trace_id:traceId,
  run_id:data.gap_analysis.run_id,
  test_id:ctx.test_id,
  gap_analysis:data.gap_analysis,
  validation:data.validation,
  generation_gate:data.generation_gate,
  trace_context:ctx,
  otlp_payload:{resourceSpans:[{resource:{attributes:[attr('service.name','prd-genie-n8n'),attr('deployment.environment.name',ctx.environment)]},scopeSpans:[{scope:{name:'prd-genie-n8n',version:ctx.workflow_version},spans:[root,generation,validation,gate]}]}]}
}}];

